/* 0x02053bb4 (0x48 bytes) InputStream_construct (Ghidra: FUN_02053bb4)
 * file: name */
/* An input stream: from a ROM file (InputStream_open) or the cartridge's backup memory
 * (InputStream_openBackup), read in pieces of at most 0x4000 bytes into one buffer the streams
 * share. mode 1: a failed backup read is reported as a write error. */
InputStream *InputStream_construct( InputStream *self, int mode ) {
	self->app = app;
	self->mode = mode;
	self->isOpen = 0;
	self->pos = 0;
	self->size = 0;
	self->lockId = (u16)OS_GetLockID();
	self->buffer = streamBuffer;
	return self;
}

/* 0x02053bfc (0x8c bytes) InputStream_open (Ghidra: FUN_02053bfc)
 * file: name */
/* The ROM file path ("rom:/sounds/headers.bin", ...) */
int InputStream_open( InputStream *self, const char *path ) {
	self->buffer = streamBuffer;
	FS_InitFile( &self->file );
	App_updateMemUsed( self->app );
	if ( !FS_OpenFile( &self->file, path ) ) {
		App_setErrorCodeRaw( self->app, -1 );
		App_setErrorStr( self->app, "Can't open %s.", path );
		return 0;
	}
	self->isOpen = 1;
	self->size = (int)( self->file.bottom - self->file.top );
	self->pos = 0;
	self->fromBackup = 0;
	return 1;
}

/* 0x02053c88 (0x50 bytes) InputStream_openBackup (Ghidra: FUN_02053c88)
 * file: name */
/* size bytes of the backup memory (the saves) from offset; 0 if the cartridge has none */
int InputStream_openBackup( InputStream *self, u32 offset, int size ) {
	self->buffer = streamBuffer;
	if ( !self->app->hasBackup ) {
		return 0;
	}
	self->backupPos = offset;
	self->backupStart = offset;
	self->size = size;
	self->pos = 0;
	self->isOpen = 1;
	self->fromBackup = 1;
	return 1;
}

/* 0x02053cd8 (0x30 bytes) InputStream_close (Ghidra: FUN_02053cd8)
 * file: name */
void InputStream_close( InputStream *self ) {
	if ( !self->fromBackup ) {
		FS_CloseFile( &self->file );
	}
	self->isOpen = 0;
	App_updateMemUsed( self->app );
}

/* 0x02053d08 (0x80 bytes) InputStream_fill (Ghidra: FUN_02053d08)
 * file: name */
/* The next n bytes into the buffer, read from pos 0 by InputStream_readInt and the like */
int InputStream_fill( InputStream *self, int n ) {
	self->pos = 0;
	if ( n > STREAM_BUFFER_SIZE ) {
		App_setErrorCodeRaw( self->app, -1 );
		App_setErrorStr( self->app, "Buffer overflow %i/%i!", n, STREAM_BUFFER_SIZE );
		return 0;
	}
	if ( InputStream_read( self, self->buffer, n ) != n ) {
		App_setErrorCodeRaw( self->app, -1 );
		App_setErrorStr( self->app, "Truncated read." );
	}
	return 1;
}

/* 0x02053d88 (0x12c bytes) InputStream_read (Ghidra: FUN_02053d88)
 * file: name */
/* n bytes of the file to dst; returns how many (from the backup always n: a failed read shows
 * the game's "save could not be read / written" screen) */
int InputStream_read( InputStream *self, void *dst, int n ) {
	int r;

	if ( self->fromBackup ) {
		if ( self->backupStart + (u32)self->size < self->backupPos + (u32)n ) {
			App_setErrorCodeRaw( self->app, -1 );
			App_setErrorStr( self->app, "Attempting to read outside the file boundries: 0x%x-0x%x",
				self->backupStart, self->backupStart + self->size );
		}
		CARD_LockBackup( self->lockId );
		if ( !CARDi_RequestStreamCommand( self->backupPos, (u32)dst, (u32)n, NULL, NULL, 0,
										  CARD_REQ_READ_BACKUP, 1, CARD_REQUEST_MODE_RECEIVE ) ) {
			self->cardResult = CARD_GetResultCode();
			App_showSaveError( self->app, self->mode == 0 ? 0xdc : 0xdd );
		}
		self->backupPos += (u32)n;
		CARD_UnlockBackup( self->lockId );
		return n;
	}
	r = FS_ReadFile( &self->file, dst, n );
	if ( r == -1 ) {
		App_setErrorCodeRaw( self->app, -1 );
		App_setErrorStr( self->app, "Failed to read." );
		return 0;
	}
	return r;
}

/* 0x02053eb4 (0x18 bytes) InputStream_readIntDirect (Ghidra: FUN_02053eb4)
 * file: name */
/* 4 bytes straight from the file (not through the buffer) */
int InputStream_readIntDirect( InputStream *self ) {
	int v;
	InputStream_read( self, &v, 4 );
	return v;
}

/* 0x02053ecc (0xe4 bytes) InputStream_readCompressed (Ghidra: FUN_02053ecc)
 * file: name */
/* An LZ77-compressed block of packedSize bytes (its header, already read, says how big it is
 * unpacked) into dst, at most maxSize; returns the size, or -1 */
int InputStream_readCompressed( InputStream *self, const u32 *header, void *dst, u32 maxSize, u32 packedSize ) {
	u32		size = *header >> 8, n;
	MIUncompContextLZ ctx;

	if ( maxSize < size ) {
		App_setErrorCodeRaw( self->app, -1 );
		App_setErrorStr( self->app, "Failed to read." );
		return -1;
	}
	MI_InitUncompContextLZ( &ctx, dst, header );
	do {
		n = packedSize > STREAM_BUFFER_SIZE ? STREAM_BUFFER_SIZE : packedSize;
		InputStream_fill( self, (int)n );
		packedSize -= n;
	} while ( MI_ReadUncompLZ8( &ctx, self->buffer, n ) != 0 );
	if ( packedSize != 0 ) {
		App_setErrorCodeRaw( self->app, -1 );
		App_setErrorStr( self->app, "Failed to read." );
		return -1;
	}
	DC_FlushRange( dst, size );
	return (int)size;
}

/* 0x02053fb0 (0xa0 bytes) InputStream_seek (Ghidra: FUN_02053fb0)
 * file: name */
/* To offset (relative: from here); the buffer is emptied. Out of the file: a debug break. */
void InputStream_seek( InputStream *self, int relative, u32 offset ) {
	int ok = 1;

	if ( !self->fromBackup ) {
		ok = FS_SeekFile( &self->file, (int)offset, relative ? FS_SEEK_CUR : FS_SEEK_SET );
	} else if ( !relative ) {
		self->backupPos = self->backupStart + offset;
		ok = offset <= (u32)self->size;
	} else {
		self->backupPos += offset;
		if ( self->backupPos >= self->backupStart + (u32)self->size ) {
			ok = 0;
		}
	}
	self->pos = 0;
	if ( !ok ) {
		OS_DebugBreak();
	}
}

