/* 0x020542d4 (0x9c bytes) OutputStream_write
 * BREW: OutputStream_write 0x00002c20
 * file: name */
/* n bytes into the buffer (0x4000), written out when it is full; flush: at once */
void OutputStream_write( OutputStream *self, const void *data, int n, int flush ) {
	const u8 *src = data;
	int k;

	if ( !src ) {
		OS_DebugBreak();
	}
	for ( ; n > 0; n -= k ) {
		k = n > STREAM_BUFFER_SIZE ? STREAM_BUFFER_SIZE : n;
		if ( (u32)( STREAM_BUFFER_SIZE - self->buffered ) < (u32)k ) {
			OutputStream_flush( self );
		}
		MI_CpuCopy8( src, outputBuffer + self->buffered, (u32)k );
		self->buffered += (u32)k;
		src += k;
	}
	if ( flush ) {
		OutputStream_flush( self );
	}
}

